{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run():
	var current_health: int = 15
	var damage: int = 20
	var new_health := maxi(0, current_health - damage)
	return new_health
",
   "domanda": "Quanto vale `new_health` alla fine?",
   "spiegazione": "`current_health - damage` fa `-5`. La funzione `maxi(0, -5)` sceglie il valore più alto tra 0 e -5, quindi restituisce `0`. La vita non scende mai sotto zero grazie a questa regola."
  },
  {
   "codice": "extends RefCounted


func run():
	var spawn_count: int = 5
	var spawn_interval: float = 1.5
	var total_time: float = (spawn_count - 1) * spawn_interval
	return total_time
",
   "domanda": "Che numero restituisce `run()`?",
   "spiegazione": "Ci sono 5 nemici, ma gli intervalli tra le nascite sono 4 (il primo nasce subito a tempo 0). Quindi si calcola `(5 - 1) * 1.5`, che fa `6.0`."
  },
  {
   "codice": "extends RefCounted


func run():
	var base_speed: float = 100.0
	var speed_multiplier: float = 1.5
	var final_speed := base_speed * speed_multiplier
	return final_speed
",
   "domanda": "Quanto vale `final_speed`?",
   "spiegazione": "`100.0 * 1.5` dà `150.0`."
  },
